import itertools

def can_partition(n):
    # Numbers are 1, 2, ..., 2n
    # Differences are 1, 2, ..., n
    nums = list(range(1, 2*n + 1))
    used = [False] * (2*n + 1)

    def backtrack(diff):
        if diff == 0:
            return True

        # Try to find a pair with difference 'diff'
        for i in range(1, 2*n - diff + 1):
            if not used[i] and not used[i + diff]:
                used[i] = True
                used[i + diff] = True
                if backtrack(diff - 1):
                    return True
                used[i] = False
                used[i + diff] = False
        return False

    return backtrack(n)

for n in range(1, 11):
    print(f"n={n}, can_partition={can_partition(n)}")
